import React from 'react';

const ProjectItem = ({ project }) => {
  const getStatusColor = (status) => {
    switch (status) {
      case 'completed':
        return 'bg-green-500';
      case 'training':
        return 'bg-yellow-500 animate-pulse';
      case 'generating':
        return 'bg-blue-500 animate-pulse';
      default:
        return 'bg-gray-500';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'completed':
        return 'Ready';
      case 'training':
        return 'Training';
      case 'generating':
        return 'Generating';
      default:
        return 'Unknown';
    }
  };

  return (
    <div className="p-4 glass-effect rounded-lg hover:bg-white/10 transition-colors cursor-pointer group">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-white font-medium group-hover:text-white/90 transition-colors">
          {project.name}
        </h3>
        <div className={`w-2 h-2 rounded-full ${getStatusColor(project.status)}`}></div>
      </div>

      <div className="flex items-center justify-between">
        <span className="text-white/60 text-sm">{project.lastModified}</span>
        <span className="text-white/40 text-xs">{getStatusText(project.status)}</span>
      </div>
    </div>
  );
};

export default ProjectItem;
